/**
 * Pictogrammes des valeurs et de l'archétype (Figma, écran À propos).
 *
 * Tracés exportés de Figma, dont la couleur passe en `currentColor` : la
 * maquette les emploie en bleu de marque sur fond clair et en bleu clair sur
 * fond sombre, et c'est le parent qui décide.
 *
 * Chaque glyphe garde ses dimensions propres — un éclair est plus étroit qu'une
 * cible — et se centre dans une boîte de 30px, celle de la maquette.
 */
function Boite({ children }: { children: React.ReactNode }) {
  return (
    <span className="inline-flex size-[30px] shrink-0 items-center justify-center">{children}</span>
  );
}


