export type NomPictoTrait =
  | "diplome"
  | "eclair"
  | "boucle"
  | "cible"
  | "bouclier"
  | "direction"
  | "ampoule"
  | "personne";

const parNom: Record<NomPictoTrait, () => React.ReactElement> = {
  diplome: PictoDiplome,
  eclair: PictoEclair,
  boucle: PictoBoucle,
  cible: PictoCible,
  bouclier: PictoBouclier,
  direction: PictoDirection,
  ampoule: PictoAmpoule,
  personne: PictoPersonne,
};

/** Le pictogramme choisi en back-office, résolu par son nom. */
export function pictoTrait(nom: NomPictoTrait) {
  const Picto = parNom[nom];
  return Picto ? <Picto /> : null;
}
